export const GIMMICKS: Gimmick[] = GIMMICK_SEEDS.map(deriveGimmickDefaults);

export function gimmickById(id: string): Gimmick | undefined {
  return GIMMICKS.find((g) => g.id === id);
}

/** Every category a gimmick can carry, in the order they should list in a picker. */
export function gimmickCategories(): string[] {
  return [...new Set(GIMMICKS.map((g) => g.category))];
}
